func assertComputedMapClean(t *testing.T, diff *terraform.InstanceDiff, mapPrefix string) {
	t.Helper()
	countKey := mapPrefix + ".%"
	if got := diff.Attributes[countKey]; got == nil || !got.NewComputed {
		t.Errorf("expected %s to have NewComputed=true, got %#v", countKey, got)
	}
	for k, attrDiff := range diff.Attributes {
		if strings.HasPrefix(k, mapPrefix+".") && k != countKey {
			t.Errorf("expected no element diffs under NewComputed map %s, but found %s = %#v", mapPrefix, k, attrDiff)
		}
	}
}

